// ===== Manifold WASM 接入（方案A）=====
const MANIFOLD_WASM_URL = '/manifold/manifold.wasm';
let manifoldWasm = null;
let manifoldApi = null;
let manifoldInitPromise = null;
let manifoldLastError = null;
const MANIFOLD_SOFT_RESET_EDIT_THRESHOLD = 10;
const MANIFOLD_SOFT_RESET_COOLDOWN_MS = 12000;
const manifoldSoftResetState = {
    editOpsSinceReset: 0,
    lastResetAt: 0,
    inProgress: false
};

async function ensureManifoldReady() {
    if (manifoldApi) return manifoldApi;
    if (!manifoldInitPromise) {
        manifoldInitPromise = (async () => {
            const wasm = await ManifoldModule({
                locateFile: () => MANIFOLD_WASM_URL
            });
            wasm.setup();
            if (!wasm.Manifold) {
                throw new Error('Manifold 初始化失败：缺少 Manifold API');
            }
            manifoldWasm = wasm;
            manifoldApi = wasm.Manifold;
            manifoldLastError = null;
            return manifoldApi;
        })().catch((err) => {
            manifoldInitPromise = null;
            manifoldLastError = err;
            throw err;
        });
    }
    return manifoldInitPromise;
}

function exposeManifoldDebugTools() {
    // 便于你在浏览器控制台做自检：window.manifoldTools.testBoolean()
    window.manifoldTools = {
        ensureReady: ensureManifoldReady,
        testBoolean: async () => {
            const Manifold = await ensureManifoldReady();
            const box = Manifold.cube([1, 1, 1], true);
            const ball = Manifold.sphere(0.7, 48);
            const result = box.subtract(ball);
            const mesh = result.getMesh();
            const triangleCount = mesh?.triVerts ? Math.floor(mesh.triVerts.length / 3) : 0;
            box.delete();
            ball.delete();
            result.delete();
            return { ok: true, triangleCount };
        },
        getModule: () => manifoldWasm,
        softReset: (reason = 'manual') => requestManifoldSoftReset(reason),
        markDirty: (reason = 'manual') => markManifoldDirtyByEdit(reason),
        getStatus: () => ({
            ready: !!manifoldApi,
            initializing: !!manifoldInitPromise && !manifoldApi,
            error: manifoldLastError ? String(manifoldLastError?.message || manifoldLastError) : null
        }),
        getResetState: () => ({
            ...manifoldSoftResetState,
            threshold: MANIFOLD_SOFT_RESET_EDIT_THRESHOLD,
            cooldownMs: MANIFOLD_SOFT_RESET_COOLDOWN_MS
        })
    };
}

// 提前暴露调试工具，避免初始化失败时 window.manifoldTools 不存在
