function manifoldizeThreeGeometry(inputGeometry, debugTag = 'unknown', options = null) {
    if (!inputGeometry || !manifoldApi || !manifoldWasm?.Mesh) return inputGeometry;
    try {
        const posAttr = inputGeometry.getAttribute?.('position');
        if (!posAttr || !posAttr.array) return inputGeometry;

        const vertProperties = new Float32Array(posAttr.array);
        let triVerts;
        if (inputGeometry.index && inputGeometry.index.array) {
            triVerts = new Uint32Array(inputGeometry.index.array);
        } else {
            triVerts = new Uint32Array(posAttr.count);
            for (let i = 0; i < posAttr.count; i++) triVerts[i] = i;
        }

        const meshInit = {
            numProp: 3,
            vertProperties,
            triVerts
        };
        if (options && Number.isFinite(options.tolerance)) meshInit.tolerance = options.tolerance;
        const mesh = new manifoldWasm.Mesh(meshInit);
        const skipMerge = !!(options && options.skipMerge);
        if (!skipMerge && typeof mesh.merge === 'function') mesh.merge();

        const manifoldObj = new manifoldApi(mesh);
        const out = manifoldObj.getMesh();
        const outGeometry = new THREE.BufferGeometry();
        outGeometry.setAttribute('position', new THREE.BufferAttribute(out.vertProperties, 3));
        outGeometry.setIndex(new THREE.BufferAttribute(out.triVerts, 1));
        outGeometry.computeVertexNormals();

        if (typeof manifoldObj.delete === 'function') manifoldObj.delete();
        if (typeof mesh.delete === 'function') mesh.delete();
        if (typeof inputGeometry.dispose === 'function') inputGeometry.dispose();

        return outGeometry;
    } catch (err) {
        console.warn(`[PolyRebuild] Manifold 墙体稳健化失败(${debugTag})，回退原几何`, err);
        return inputGeometry;
    }
}

function markManifoldDirtyByEdit(reason = 'edit') {
    manifoldSoftResetState.editOpsSinceReset += 1;
    if (manifoldSoftResetState.editOpsSinceReset < MANIFOLD_SOFT_RESET_EDIT_THRESHOLD) return;
    requestManifoldSoftReset(`auto:${reason}`);
}

let collectPolyRebuildBeamRootsForSoftReset = null;
let rebuildPolyRebuildBeamRootMeshForSoftReset = null;
let refreshWallBooleanPipelineForSoftReset = null;

function collectUniquePolyRoots() {
    const walls = new Set();
    const extrudes = new Set();
    const floors = new Set();
    (polyRebuildState.wallSegments || []).forEach((seg) => { if (seg?.wallRoot) walls.add(seg.wallRoot); });
    (polyRebuildState.extrudePolygons || []).forEach((poly) => { if (poly?.root) extrudes.add(poly.root); });
    (polyRebuildState.floorPolygons || []).forEach((poly) => { if (poly?.root) floors.add(poly.root); });
    const beamRoots = (typeof collectPolyRebuildBeamRootsForSoftReset === 'function')
        ? collectPolyRebuildBeamRootsForSoftReset()
        : [];
    return {
        wallRoots: Array.from(walls).filter(Boolean),
        extrudeRoots: Array.from(extrudes).filter(Boolean),
        floorRoots: Array.from(floors).filter(Boolean),
        beamRoots
    };
}

async function performManifoldSoftReset(reason = 'manual') {
    const roots = collectUniquePolyRoots();
    manifoldApi = null;
    manifoldWasm = null;
    manifoldInitPromise = null;
    manifoldLastError = null;
    await ensureManifoldReady();
    roots.wallRoots.forEach((root) => {
        if (!root?.userData) return;
        if (root.userData.polyCombinedWallBaseGeometry) {
            try { root.userData.polyCombinedWallBaseGeometry.dispose(); } catch (_e) {}
            root.userData.polyCombinedWallBaseGeometry = null;
        }
    });
    roots.extrudeRoots.forEach((root) => {
        if (!root?.userData) return;
        if (root.userData.polyExtrudeBaseGeometry) {
            try { root.userData.polyExtrudeBaseGeometry.dispose(); } catch (_e) {}
            root.userData.polyExtrudeBaseGeometry = null;
        }
    });
    roots.floorRoots.forEach((root) => {
        if (!root?.userData) return;
        if (root.userData.polyFloorBaseGeometry) {
            try { root.userData.polyFloorBaseGeometry.dispose(); } catch (_e) {}
            root.userData.polyFloorBaseGeometry = null;
        }
    });
    rebuildPolyRebuildWallSegments();
    const touchedWallRoots = new Set((polyRebuildState.wallSegments || []).map((seg) => seg?.wallRoot).filter(Boolean));
    rebuildFloorsForWallRoots(Array.from(touchedWallRoots));
    (roots.extrudeRoots || []).forEach((root) => rebuildPolyRebuildExtrudeRootMesh(root));
    (roots.floorRoots || []).forEach((root) => rebuildPolyRebuildFloorRootMesh(root));
    (roots.beamRoots || []).forEach((root) => {
        if (!root) return;
        root.traverse((child) => {
            if (!child?.userData?.polyBeamBaseGeometry) return;
            try { child.userData.polyBeamBaseGeometry.dispose(); } catch (_e) {}
            child.userData.polyBeamBaseGeometry = null;
        });
        if (typeof rebuildPolyRebuildBeamRootMeshForSoftReset === 'function') {
            rebuildPolyRebuildBeamRootMeshForSoftReset(root);
        }
    });
    if (typeof refreshWallBooleanPipelineForSoftReset === 'function') {
        refreshWallBooleanPipelineForSoftReset();
    } else if (typeof refreshWallBooleanPipeline === 'function') {
        refreshWallBooleanPipeline();
    }
    manifoldSoftResetState.editOpsSinceReset = 0;
    manifoldSoftResetState.lastResetAt = Date.now();
    showPickFeedback(`布尔引擎已重建（${reason}）`);
}

function requestManifoldSoftReset(reason = 'manual') {
    const now = Date.now();
    if (manifoldSoftResetState.inProgress) return;
    if (now - manifoldSoftResetState.lastResetAt < MANIFOLD_SOFT_RESET_COOLDOWN_MS) return;
    manifoldSoftResetState.inProgress = true;
    Promise.resolve()
        .then(() => performManifoldSoftReset(reason))
        .catch((err) => {
            console.warn('[PolyRebuild] Manifold 软重置失败', err);
            showPickFeedback('布尔引擎重建失败，请稍后重试');
        })
        .finally(() => {
            manifoldSoftResetState.inProgress = false;
        });
}

