// 调试开关：true 表示暂停所有安全防护（仅本地排障时临时开启）
const DEBUG_DISABLE_SECURITY_PROTECTION = false;
// 如果是公开链接，或者是这几个线下测试入口，或者是所有者在后台查看（非只读模式），直接跳过防护机制
// 【新增】如果是克隆模式（密码分享），因为最终是用户自己克隆到自己名下的，所以也不需要防截屏与水印防护
if (DEBUG_DISABLE_SECURITY_PROTECTION || (((isPublic || isLocalTest || !isViewOnly) && !isSharePwd && document.body) || isSharePwd)) {
    document.body.classList.add('public-view');
    console.log("当前为开发/测试环境或所有者模式或克隆副本模式，防截屏与水印防护已关闭");
} else {
    // ==========================================
    // ===[私密项目：强效防截屏与录屏防护] ===
    // ==========================================

    // 1. 尝试通知原生 App 外壳（如果有的话）开启系统级防截屏
    try {
        if (window.Android && window.Android.setSecure) {
            window.Android.setSecure(true); // 通知安卓端开启 FLAG_SECURE
        } else if (window.webkit && window.webkit.messageHandlers && window.webkit.messageHandlers.setSecure) {
            window.webkit.messageHandlers.setSecure.postMessage(true); // 通知 iOS 端开启安全图层
        }
    } catch(e) {}

    // 2. 防 iOS/安卓 任务列表偷录：切屏或进入后台时，瞬间隐藏 3D 画布
    document.addEventListener("visibilitychange", () => {
        const container = document.getElementById('container');
        if (document.hidden) {
            container.style.opacity = '0'; // 进入后台瞬间变黑
        } else {
            // 切回前台时，延迟 0.2 秒恢复画面，防止录屏软件捕捉到第一帧
            setTimeout(() => container.style.opacity = '1', 200); 
        }
    });

    // 3. 失去焦点时模糊画布（防分屏或安卓悬浮窗录制）
    window.addEventListener('blur', () => {
        document.getElementById('container').style.filter = 'blur(25px)';
    });
    window.addEventListener('focus', () => {
        document.getElementById('container').style.filter = 'none';
    });

    // 4. 生成满屏“防物理拍照”追踪暗水印
    function initSecureWatermark() {
        const wm = document.createElement('div');
        wm.style.position = 'fixed';
        wm.style.top = '0'; 
        wm.style.left = '0';
        wm.style.width = '100vw'; 
        wm.style.height = '100vh';
        wm.style.pointerEvents = 'none'; // 保证不阻挡用户的 3D 操作滑动
        wm.style.zIndex = '999999';
        wm.style.display = 'flex'; 
        wm.style.flexWrap = 'wrap';
        wm.style.overflow = 'hidden';
        wm.style.opacity = '0.5'; // 极低透明度，肉眼难辨但不影响通过 PS 调曲线找出版权来源

        for(let i = 0; i < 80; i++) {
            const span = document.createElement('div');
            // 可以替换为你的版权声明或获取访客的特征码
            span.innerText = "blackadg.com"; 
            span.style.color = "#ffffff";
            span.style.padding = "30px 20px";
            span.style.fontSize = "13px";
            span.style.transform = "rotate(-30deg)";
            span.style.whiteSpace = "nowrap";
            span.style.userSelect = "none";
            wm.appendChild(span);
        }
        document.body.appendChild(wm);
        
        // 禁止长按保存、选中等基础手机行为
        document.body.style.userSelect = 'none';
        document.body.style.webkitUserSelect = 'none';
        document.body.style.webkitTouchCallout = 'none';
    }
    
    // 延迟 0.5 秒加载暗水印
    setTimeout(initSecureWatermark, 500);
}

        // 【关键修复】如果是分享出来的只读模式，强制忽略本地 Token。
        // 这避免了因为使用他人账号 Token 或 过期 Token 导致请求被拦截（401/403），
        // 从而使得常规浏览器拥有与无痕模式完全相同的畅通体验。
        let myToken = null;
        if (isSharePwd) {
            myToken = window.localStorage.getItem('my_3dgs_token');
            if (!myToken) {
                alert("查看此加密分享并保存副本，需要先登录您的账号。");
                const returnUrl = encodeURIComponent(window.location.href);
                window.location.href = 'login.html?return=' + returnUrl;
            }
        } else {
            myToken = isViewOnly ? null : window.localStorage.getItem('my_3dgs_token');
        }

        // 游客 / 只读分享：不带 Cookie，避免微信 WebView 残留过期会话导致 Directus 401
        // （从未登录过的微信号可打开，曾登录过的会 401 —— 同源 fetch 默认 same-origin 会带脏 Cookie）
        const restGuestOptions = { credentials: 'omit' };
        const guestFetchInit = (init = {}) => ({ ...init, credentials: 'omit' });

        // 如果没有 Token 且不是只读分享模式，才跳转登录
        if (!myToken && !isViewOnly && !isSharePwd) window.location.href = 'login.html';

        function withTimeout(promise, ms, code = 'REQUEST_TIMEOUT') {
            return Promise.race([
                promise,
                new Promise((_, reject) => {
                    setTimeout(() => {
                        const err = new Error(code);
                        err.code = code;
                        reject(err);
                    }, ms);
                })
            ]);
        }

        // --- 商业化：获取用户订阅等级 ---
        let currentUser = null;
        if (myToken) {
            try {
                // 如果有 Token，尝试获取用户信息
                let tempClientBuilder = createDirectus(window.location.origin + '/api');
                tempClientBuilder = tempClientBuilder.with(staticToken(myToken));
                const tempClient = tempClientBuilder.with(rest());
                currentUser = await withTimeout(
                    tempClient.request(readMe()),
                    2500,
                    'BOOT_README_TIMEOUT'
                );
            } catch (err) {
                console.warn('获取当前用户失败，Token 可能已过期', err);
            }
        }

        let clientBuilder = createDirectus(window.location.origin + '/api');
        if (myToken) {
            clientBuilder = clientBuilder.with(staticToken(myToken));
        }
        let client = clientBuilder.with(myToken ? rest() : rest(restGuestOptions)); // 改用 let

        // ================== 无感续期核心逻辑 ==================
        let isRefreshing = false;
        let refreshPromise = null;

        async function refreshMyToken() {
            if (isRefreshing) return refreshPromise;
            isRefreshing = true;
            
            refreshPromise = (async () => {
                const refreshToken = window.localStorage.getItem('my_3dgs_refresh_token');
                if (!refreshToken) return false;
                try {
                    const res = await fetch(window.location.origin + '/api/auth/refresh', {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({ refresh_token: refreshToken, mode: 'json' })
                    });
                    if (!res.ok) return false;
                    
                    const data = await res.json();
                    if (data?.data?.access_token) {
                        window.localStorage.setItem('my_3dgs_token', data.data.access_token);
                        if (data.data.refresh_token) {
                            window.localStorage.setItem('my_3dgs_refresh_token', data.data.refresh_token);
                        }
                        
                        myToken = data.data.access_token; // 更新全局变量，保证后续 fetch 图片/模型时用新 Token
                        
                        let newBuilder = createDirectus(window.location.origin + '/api');
                        newBuilder = newBuilder.with(staticToken(myToken));
                        client = newBuilder.with(rest());
                            
                        applyTokenWrapper(); 
                        return true;
                    }
                    return false;
                } catch (err) {
                    return false;
                } finally {
                    isRefreshing = false;
                }
            })();
            return refreshPromise;
        }

        function applyTokenWrapper() {
            const originalRequest = client.request.bind(client);
            client.request = async function(options) {
                try {
                    return await originalRequest(options);
                } catch (error) {
                    const errCode = error?.errors?.[0]?.extensions?.code;
                    const status = error?.response?.status;
                    if (errCode === 'INVALID_TOKEN' || errCode === 'TOKEN_EXPIRED' || status === 401) {
                        console.log("Token 过期，无感续期中...");
                        const success = await refreshMyToken();
                        if (success) {
                            return await client.request(options);
                        } else {
                            window.localStorage.removeItem('my_3dgs_token');
                            window.localStorage.removeItem('my_3dgs_refresh_token');
                            window.location.href = 'login.html';
                            throw new Error("登录已过期，请重新登录");
                        }
                    }
                    throw error;
                }
            };
        }

        if (myToken) {
            applyTokenWrapper(); // 仅针对已登录用户开启续期
        }

        let currentProjectName = "未命名项目";
        let activeUploads = 0;
        let totalFilesToUpload = 0;
        let completedFiles = 0;

        // ----------------------------------------------------
        // 【新增】存放本地已经要求删除，等待下次点击"保存"时正式从云端抹除的文件 ID
        let pendingDeleteFileIds = [];

        function enqueuePendingCloudFileDeletion(fileId) {
            if (!fileId || typeof fileId !== 'string') return;
            if (fileId.startsWith('temp_') || fileId.length <= 10) return;
            if (!pendingDeleteFileIds.includes(fileId)) pendingDeleteFileIds.push(fileId);
        }

        function dequeuePendingCloudFileDeletion(fileId) {
            if (!fileId || typeof fileId !== 'string') return;
            const idx = pendingDeleteFileIds.indexOf(fileId);
            if (idx >= 0) pendingDeleteFileIds.splice(idx, 1);
        }

        function isAdgSceneSidecarKey(key) {
            return isAdgRadSidecarKey(key) || isAdgCopcSidecarKey(key);
        }

        function collectFileIdsFromSceneDataNode(node, out) {
            // 克隆/保存 diff 只收用户文件，不要把 layer.rad / layer.copc 加进拷贝或删除列表。
            if (node == null) return;
            if (Array.isArray(node)) {
                node.forEach((item) => collectFileIdsFromSceneDataNode(item, out));
                return;
            }
            if (typeof node !== 'object') return;
            if (typeof node.fileId === 'string') out.add(node.fileId);
            if (typeof node.cloudId === 'string') out.add(node.cloudId);
            if (typeof node.audioId === 'string') out.add(node.audioId);
            if (typeof node.flatnessCacheFileId === 'string') out.add(node.flatnessCacheFileId);
            if (node.type === 'file' && typeof node.id === 'string') out.add(node.id);
            if (Array.isArray(node.attachments)) {
                node.attachments.forEach((att) => {
                    if (att && typeof att.id === 'string') out.add(att.id);
                });
            }
            Object.entries(node).forEach(([key, value]) => {
                if (isAdgSceneSidecarKey(key)) return;
                collectFileIdsFromSceneDataNode(value, out);
            });
        }

        function normalizeSceneDataForFileCollect(sceneData) {
            if (sceneData == null) return null;
            if (typeof sceneData === 'string') {
                try { return JSON.parse(sceneData); } catch { return null; }
            }
            return sceneData;
        }

        function collectFileIdsFromSceneData(sceneData, extraThumbId) {
            const ids = new Set();
            const data = normalizeSceneDataForFileCollect(sceneData);
            if (data) collectFileIdsFromSceneDataNode(data, ids);
            if (extraThumbId && typeof extraThumbId === 'string' && extraThumbId.length > 10 && !extraThumbId.startsWith('temp_')) {
                ids.add(extraThumbId);
            }
            return ids;
        }
        // 保存进行中暂存本次新上传的文件 ID，项目未成功写入时回滚删除
        let saveStagedFileIds = null;
        let saveBeforeUnloadHandler = null;

        function beginSaveStaging() {
            saveStagedFileIds = [];
            saveBeforeUnloadHandler = (e) => {
                e.preventDefault();
                e.returnValue = '';
            };
            window.addEventListener('beforeunload', saveBeforeUnloadHandler);
        }

        function endSaveStagingSuccess() {
            saveStagedFileIds = null;
            if (saveBeforeUnloadHandler) {
                window.removeEventListener('beforeunload', saveBeforeUnloadHandler);
                saveBeforeUnloadHandler = null;
            }
        }

        async function rollbackSaveStagedFiles() {
            const ids = saveStagedFileIds ? [...saveStagedFileIds] : [];
            saveStagedFileIds = null;
            if (saveBeforeUnloadHandler) {
                window.removeEventListener('beforeunload', saveBeforeUnloadHandler);
                saveBeforeUnloadHandler = null;
            }
            if (!ids.length) return;
            console.warn(`[保存] 回滚 ${ids.length} 个未关联项目的已上传文件`);
            await Promise.allSettled(ids.map(id =>
                client.request(deleteFile(id)).catch(e => console.warn('[保存] 回滚删除失败', id, e))
            ));
        }

        // 密码分享克隆保存：全屏持久阻塞提示
        let cloneSaveOverlayActive = false;

        function updateCloneSaveBlockingOverlay(status, detail = '', percent = null) {
            const ui = document.getElementById('clone-save-blocking-ui');
            if (!ui || !cloneSaveOverlayActive) return;
            const statusEl = document.getElementById('clone-save-status-text');
            const detailEl = document.getElementById('clone-save-detail-text');
            const fillEl = document.getElementById('clone-save-progress-fill');
            const percentEl = document.getElementById('clone-save-percent-text');
            if (statusEl && status) statusEl.innerText = status;
            if (detailEl) detailEl.innerText = detail || '';
            if (percent != null && fillEl) {
                fillEl.style.width = Math.min(100, Math.max(0, percent)) + '%';
            }
            if (percent != null && percentEl) {
                percentEl.innerText = Math.round(percent) + '%';
            }
        }

        function showCloneSaveBlockingOverlay(status = '正在准备保存…', detail = '请勿关闭窗口或退出页面。保存完成后将退回控制台，请自行重新进入项目。', percent = 0) {
            const ui = document.getElementById('clone-save-blocking-ui');
            if (!ui) return;
            cloneSaveOverlayActive = true;
            ui.classList.remove('is-complete');
            ui.classList.add('active');
            ui.style.display = 'flex';
            const uploadBar = document.getElementById('upload-status-bar');
            if (uploadBar) uploadBar.classList.remove('active');
            const titleEl = ui.querySelector('.clone-save-blocking-title');
            if (titleEl) titleEl.innerText = '正在保存项目副本';
            updateCloneSaveBlockingOverlay(status, detail, percent);
        }

        function hideCloneSaveBlockingOverlay() {
            const ui = document.getElementById('clone-save-blocking-ui');
            cloneSaveOverlayActive = false;
            if (!ui) return;
            ui.classList.remove('active', 'is-complete');
            ui.style.display = 'none';
            const titleEl = ui.querySelector('.clone-save-blocking-title');
            if (titleEl) titleEl.innerText = '正在保存项目副本';
        }

        function finishCloneSaveBlockingOverlay() {
            return new Promise((resolve) => {
                const ui = document.getElementById('clone-save-blocking-ui');
                if (!ui || !cloneSaveOverlayActive) {
                    resolve();
                    return;
                }
                ui.classList.add('is-complete');
                const titleEl = ui.querySelector('.clone-save-blocking-title');
                if (titleEl) titleEl.innerText = '保存完成';
                updateCloneSaveBlockingOverlay('已保存到您的账户，即将返回控制台。请自行重新进入项目。', '', 100);
                setTimeout(() => {
                    hideCloneSaveBlockingOverlay();
                    resolve();
                }, 2000);
            });
        }
