        function snapshotRendererToBlob(type = 'image/jpeg', quality = 0.5) {
            // toBlob 是异步的；preserveDrawingBuffer:false 时必须在同一同步回合里把 WebGL 画布拷到 2D canvas
            const src = renderer.domElement;
            const tmp = document.createElement('canvas');
            tmp.width = src.width;
            tmp.height = src.height;
            tmp.getContext('2d').drawImage(src, 0, 0);
            return new Promise((resolve, reject) => {
                tmp.toBlob((b) => (b ? resolve(b) : reject(new Error('截图失败'))), type, quality);
            });
        }
