            const last = unifiedUndoStack.length > 0 ? unifiedUndoStack[unifiedUndoStack.length - 1] : null;
            if (last && last.kind === 'pcView' && isSamePcViewState(last.state, startState)) return;
            pushUnifiedHistory({ kind: 'pcView', state: startState });
