        function restorePolyRebuildSelectionMaterial(material) {
            if (!material || !material.userData || !material.userData.polyRebuildSelOriginal) return;
            const raw = material.userData.polyRebuildSelOriginal;
            if (raw.color !== null && material.color) material.color.setHex(raw.color);
            if (raw.emissive !== null && material.emissive) material.emissive.setHex(raw.emissive);
            if (raw.emissiveIntensity !== null && typeof material.emissiveIntensity === 'number') material.emissiveIntensity = raw.emissiveIntensity;
            if (typeof raw.opacity === 'number') material.opacity = raw.opacity;
            material.transparent = !!raw.transparent;
            if (Object.prototype.hasOwnProperty.call(raw, 'colorWrite')) {
                material.colorWrite = raw.colorWrite !== false;
            }
            if (Object.prototype.hasOwnProperty.call(raw, 'depthWrite')) {
                material.depthWrite = raw.depthWrite !== false;
            }
            if (Object.prototype.hasOwnProperty.call(raw, 'depthTest')) {
                material.depthTest = raw.depthTest !== false;
            }
            if (Object.prototype.hasOwnProperty.call(raw, 'polygonOffset')) {
                material.polygonOffset = !!raw.polygonOffset;
            }
            if (Object.prototype.hasOwnProperty.call(raw, 'polygonOffsetFactor')) {
                material.polygonOffsetFactor = raw.polygonOffsetFactor;
            }
            if (Object.prototype.hasOwnProperty.call(raw, 'polygonOffsetUnits')) {
                material.polygonOffsetUnits = raw.polygonOffsetUnits;
            }
            material.needsUpdate = true;
            delete material.userData.polyRebuildSelOriginal;
        }

        function applyPolyRebuildSelectionMaterial(material, highlightHex, options = null) {
            if (!material) return;
            if (!material.userData) material.userData = {};
            if (!material.userData.polyRebuildSelOriginal) {
                material.userData.polyRebuildSelOriginal = {
                    color: material.color ? material.color.getHex() : null,
                    emissive: material.emissive ? material.emissive.getHex() : null,
                    emissiveIntensity: typeof material.emissiveIntensity === 'number' ? material.emissiveIntensity : null,
                    opacity: typeof material.opacity === 'number' ? material.opacity : 1,
                    transparent: !!material.transparent,
                    colorWrite: material.colorWrite !== false,
                    depthWrite: material.depthWrite !== false,
                    depthTest: material.depthTest !== false,
                    polygonOffset: !!material.polygonOffset,
                    polygonOffsetFactor: material.polygonOffsetFactor || 0,
                    polygonOffsetUnits: material.polygonOffsetUnits || 0
                };
            }
            if (material.color) material.color.setHex(highlightHex);
            if (material.emissive) {
                material.emissive.setHex(highlightHex);
                if (typeof material.emissiveIntensity === 'number') material.emissiveIntensity = Math.max(material.emissiveIntensity, 0.35);
            }
            // 材质视觉隐藏会把 colorWrite=false / opacity=0；选中提示必须仍能画出来
            material.colorWrite = true;
            if (typeof material.opacity === 'number') {
                material.transparent = true;
                material.opacity = Math.max(0.72, material.opacity);
            }
            // 超级实体预览常被宿主并集表面挡住(~1mm)：用 polygonOffset 贴面显示，
            // 避免 depthTest=false 造成「只有色框在飘、融合实体不动」的错觉。
            if (options && options.overlay) {
                material.depthTest = true;
                material.depthWrite = false;
                material.polygonOffset = true;
                material.polygonOffsetFactor = -4;
                material.polygonOffsetUnits = -4;
                if (typeof material.opacity === 'number') {
                    material.opacity = Math.max(0.88, material.opacity);
                }
            }
            material.needsUpdate = true;
        }

        function forEachPolyRebuildHighlightMaterial(root, callback) {
            if (!root) return;
            if (root.userData && root.userData.isPolyRebuildAssistPlane) {
                root.traverse((child) => {
                    if (!child?.userData?.isPolyRebuildAssistPlaneVisual) return;
                    const mats = Array.isArray(child.material) ? child.material : [child.material];
                    mats.filter(Boolean).forEach(callback);
                });
                return;
            }
            root.traverse((child) => {
                const mats = Array.isArray(child.material) ? child.material : [child.material];
                mats.filter(Boolean).forEach(callback);
            });
        }

        function restoreSuperEntitySelectionOverlay(root) {
            if (!root?.userData?.isPolyRebuildSuperEntityRoot) return;
            root.traverse((child) => {
                if (!child?.userData?.isPolyRebuildSuperEntityMesh) return;
                if (child.userData.polyRebuildSelRenderOrder != null) {
                    child.renderOrder = child.userData.polyRebuildSelRenderOrder;
                    delete child.userData.polyRebuildSelRenderOrder;
                }
            });
        }

        function applySuperEntitySelectionOverlay(root) {
            if (!root?.userData?.isPolyRebuildSuperEntityRoot) return;
            root.traverse((child) => {
                if (!child?.userData?.isPolyRebuildSuperEntityMesh) return;
                if (child.userData.polyRebuildSelRenderOrder == null) {
                    child.userData.polyRebuildSelRenderOrder = child.renderOrder;
                }
                child.renderOrder = Math.max(Number(child.renderOrder) || 0, 10080);
            });
        }

        function revealSuperEntityUnionShellIfHidden(material) {
            if (!material?.userData?.polySeUnionShellHidden) return;
            const b = material.userData.polySeUnionShellBackup;
            if (b) {
                if (typeof b.opacity === 'number') material.opacity = b.opacity;
                material.colorWrite = b.colorWrite !== false;
                material.transparent = !!b.transparent;
                material.needsUpdate = true;
            }
            delete material.userData.polySeUnionShellHidden;
            delete material.userData.polySeUnionShellBackup;
        }

        // 加模式：蓝色 SE 始终为主视觉，不再隐藏预览壳。
        function syncSuperEntityUnionPreviewShell() {
            (polyRebuildState.superEntities || []).forEach((entity) => {
                const mesh = entity?.mesh || entity?.root?.userData?.polySuperEntityMesh;
                const mat = mesh?.material;
                if (!mat) return;
                revealSuperEntityUnionShellIfHidden(mat);
            });
        }

        function syncPolyRebuildSelectionHighlight() {
            const roots = collectPolyRebuildSelectableRoots();
            const rootMap = new Map();
            roots.forEach(root => rootMap.set(getPolyRebuildElementId(root), root));

            const staleIds = [];
            polyRebuildState.selectedElementIds.forEach((id) => {
                if (!rootMap.has(id)) staleIds.push(id);
            });
            staleIds.forEach(id => polyRebuildState.selectedElementIds.delete(id));
            if (polyRebuildState.selectedElementLast && !polyRebuildState.selectedElementIds.has(polyRebuildState.selectedElementLast)) {
                polyRebuildState.selectedElementLast = null;
            }

            roots.forEach((root) => {
                const id = getPolyRebuildElementId(root);
                const isSelected = polyRebuildState.selectedElementIds.has(id);
                const isSE = !!root.userData?.isPolyRebuildSuperEntityRoot;
                if (!isSelected) {
                    forEachPolyRebuildHighlightMaterial(root, restorePolyRebuildSelectionMaterial);
                    restoreSuperEntitySelectionOverlay(root);
                    return;
                }
                const highlightHex = root.userData?.isPolyRebuildAssistPlane ? 0x22d3ee : 0xff8a3d;
                forEachPolyRebuildHighlightMaterial(root, (material) => {
                    if (isSE) revealSuperEntityUnionShellIfHidden(material);
                    applyPolyRebuildSelectionMaterial(material, highlightHex, isSE ? { overlay: true } : null);
                });
                if (isSE) applySuperEntitySelectionOverlay(root);
            });
            const layerItems = Array.from(document.querySelectorAll('#layer-list .layer-item'));
            layerItems.forEach((item) => {
                const obj = item.userDataObj;
                if (!obj) return;
                const root = getPolyRebuildSelectableRootFromObject(obj);
                if (!root) return;
                const id = getPolyRebuildElementId(root);
                if (!id) return;
                if (polyRebuildState.selectedElementIds.has(id)) {
                    item.style.borderColor = root.userData?.isPolyRebuildAssistPlane ? '#22d3ee' : '#ff8a3d';
                } else if (obj === activeObject) {
                    item.style.borderColor = '#f1c40f';
                } else {
                    item.style.borderColor = '#444';
                }
            });
            syncSuperEntityUnionPreviewShell();
        }

        function syncPolyRebuildAssistPlaneWorldInputs(assistPlane) {
            const worldXInput = document.getElementById('poly-rebuild-element-props-plane-world-x-input');
            const worldYInput = document.getElementById('poly-rebuild-element-props-plane-world-y-input');
            const worldZInput = document.getElementById('poly-rebuild-element-props-plane-world-z-input');
            if (!worldXInput || !worldYInput || !worldZInput) return false;
            const targetPlane = assistPlane?.userData?.isPolyRebuildAssistPlane
                ? assistPlane
                : getCurrentPolyRebuildSelectedAssistPlane();
            if (!targetPlane) return false;
            const worldPos = targetPlane.getWorldPosition(new THREE.Vector3());
            worldXInput.value = String(worldPos.x.toFixed(3));
            worldYInput.value = String(worldPos.y.toFixed(3));
            worldZInput.value = String(worldPos.z.toFixed(3));
            return true;
        }

        function getPolyRebuildAssistPlaneLocalDatum(assistPlane, forceReset = false) {
            if (!assistPlane || !assistPlane.userData) return null;
            assistPlane.updateMatrixWorld(true);
            const worldPos = assistPlane.getWorldPosition(new THREE.Vector3());
            const worldQuat = assistPlane.getWorldQuaternion(new THREE.Quaternion());
            const hasPos = Array.isArray(assistPlane.userData.assistPlaneLocalDatumPosition) && assistPlane.userData.assistPlaneLocalDatumPosition.length === 3;
            const hasQuat = Array.isArray(assistPlane.userData.assistPlaneLocalDatumQuaternion) && assistPlane.userData.assistPlaneLocalDatumQuaternion.length === 4;
            if (forceReset || !hasPos || !hasQuat) {
                assistPlane.userData.assistPlaneLocalDatumPosition = worldPos.toArray();
                assistPlane.userData.assistPlaneLocalDatumQuaternion = worldQuat.toArray();
            }
            return {
                position: new THREE.Vector3().fromArray(assistPlane.userData.assistPlaneLocalDatumPosition),
                quaternion: new THREE.Quaternion().fromArray(assistPlane.userData.assistPlaneLocalDatumQuaternion)
            };
        }

        function getPolyRebuildAssistPlaneRole(assistPlane) {
            if (!assistPlane || !assistPlane.userData?.isPolyRebuildAssistPlane) return 'base';
            return assistPlane.userData.assistPlaneRole === 'ceiling' ? 'ceiling' : 'base';
        }

        function syncPolyRebuildAssistPlaneLocalInputs(assistPlane) {
            const localXInput = document.getElementById('poly-rebuild-element-props-plane-local-x-input');
            const localYInput = document.getElementById('poly-rebuild-element-props-plane-local-y-input');
            const localZInput = document.getElementById('poly-rebuild-element-props-plane-local-z-input');
            if (!localXInput || !localYInput || !localZInput) return false;
            const targetPlane = assistPlane?.userData?.isPolyRebuildAssistPlane
                ? assistPlane
                : getCurrentPolyRebuildSelectedAssistPlane();
            if (!targetPlane) return false;
            const datum = getPolyRebuildAssistPlaneLocalDatum(targetPlane, false);
            if (!datum) return false;
            const worldPos = targetPlane.getWorldPosition(new THREE.Vector3());
            const worldQuat = targetPlane.getWorldQuaternion(new THREE.Quaternion());
            const modelLocalOffset = worldPos.clone().sub(datum.position).applyQuaternion(worldQuat.clone().invert());
            // UI轴约定：X=平面X，Y=法向(模型+Z)，Z=平面Y反向(-模型Y)
            const uiLocalX = modelLocalOffset.x;
            const uiLocalY = modelLocalOffset.z;
            const uiLocalZ = -modelLocalOffset.y;
            localXInput.value = String(uiLocalX.toFixed(3));
            localYInput.value = String(uiLocalY.toFixed(3));
            localZInput.value = String(uiLocalZ.toFixed(3));
            return true;
        }

        function syncPolyRebuildElementPropsPanelUi() {
            const panel = document.getElementById('poly-rebuild-element-props-ui');
            const wallPage = document.getElementById('poly-rebuild-element-props-page-wall');
            const planePage = document.getElementById('poly-rebuild-element-props-page-assist-plane');
            const extrudePage = document.getElementById('poly-rebuild-element-props-page-extrude');
            const wallName = document.getElementById('poly-rebuild-element-props-wall-name');
            const wallHeightInput = document.getElementById('poly-rebuild-element-props-wall-height-input');
            const wallHeightLockBtn = document.getElementById('poly-rebuild-element-props-wall-height-lock-btn');
            const wallThicknessInput = document.getElementById('poly-rebuild-element-props-wall-thickness-input');
            const wallThicknessLockBtn = document.getElementById('poly-rebuild-element-props-wall-thickness-lock-btn');
            const wallCenterLineOffsetInput = document.getElementById('poly-rebuild-element-props-wall-centerline-offset-input');
            const wallOffsetInput = document.getElementById('poly-rebuild-element-props-wall-offset-input');
            const wallAlignCenterBtn = document.getElementById('poly-rebuild-element-props-wall-align-center-btn');
            const wallAlignInnerBtn = document.getElementById('poly-rebuild-element-props-wall-align-inner-btn');
            const wallAlignOuterBtn = document.getElementById('poly-rebuild-element-props-wall-align-outer-btn');
            const planeName = document.getElementById('poly-rebuild-element-props-plane-name');
            const planeSizeXInput = document.getElementById('poly-rebuild-element-props-plane-size-x-input');
            const planeSizeYInput = document.getElementById('poly-rebuild-element-props-plane-size-y-input');
            const planeGridInput = document.getElementById('poly-rebuild-element-props-plane-grid-step-input');
            const planeWorldXInput = document.getElementById('poly-rebuild-element-props-plane-world-x-input');
            const planeWorldYInput = document.getElementById('poly-rebuild-element-props-plane-world-y-input');
            const planeWorldZInput = document.getElementById('poly-rebuild-element-props-plane-world-z-input');
            const planeLocalXInput = document.getElementById('poly-rebuild-element-props-plane-local-x-input');
            const planeLocalYInput = document.getElementById('poly-rebuild-element-props-plane-local-y-input');
            const planeLocalZInput = document.getElementById('poly-rebuild-element-props-plane-local-z-input');
            const planeTitle = document.getElementById('poly-rebuild-element-props-plane-title');
            const planeAlignClipBtn = document.getElementById('poly-rebuild-element-props-plane-align-clip-btn');
            const planeCopyBtn = document.getElementById('poly-rebuild-element-props-plane-copy-btn');
            const planeFullCopyBtn = document.getElementById('poly-rebuild-element-props-plane-full-copy-btn');
            const extrudeName = document.getElementById('poly-rebuild-element-props-extrude-name');
            const extrudeTitle = document.getElementById('poly-rebuild-element-props-extrude-title');
            const extrudeHeightLabel = document.getElementById('poly-rebuild-element-props-extrude-height-label');
            const extrudeHeightInput = document.getElementById('poly-rebuild-element-props-extrude-height-input');
            const extrudeHeightLockBtn = document.getElementById('poly-rebuild-element-props-extrude-height-lock-btn');
            const extrudeOffsetInput = document.getElementById('poly-rebuild-element-props-extrude-offset-input');
            const extrudeOffsetRow = document.getElementById('poly-rebuild-element-props-extrude-offset-row');
            const loftPage = document.getElementById('poly-rebuild-element-props-page-loft');
            const loftName = document.getElementById('poly-rebuild-element-props-loft-name');
            const loftAlignCenterBtn = document.getElementById('poly-rebuild-element-props-loft-align-center-btn');
            const loftAlignTopBtn = document.getElementById('poly-rebuild-element-props-loft-align-top-btn');
            const loftAlignBottomBtn = document.getElementById('poly-rebuild-element-props-loft-align-bottom-btn');
            const loftAlignLeftBtn = document.getElementById('poly-rebuild-element-props-loft-align-left-btn');
            const loftAlignRightBtn = document.getElementById('poly-rebuild-element-props-loft-align-right-btn');
            const loftDiameterInput = document.getElementById('poly-rebuild-element-props-loft-diameter-input');
            const loftDiameterLockBtn = document.getElementById('poly-rebuild-element-props-loft-diameter-lock-btn');
            const loftFilletEnabledInput = document.getElementById('poly-rebuild-element-props-loft-fillet-enabled');
            const loftFilletRadiusInput = document.getElementById('poly-rebuild-element-props-loft-fillet-radius-input');
            const loftTubeSegmentsInput = document.getElementById('poly-rebuild-element-props-loft-tube-segments-input');
            const loftRectPage = document.getElementById('poly-rebuild-element-props-page-loft-rect');
            const loftRectName = document.getElementById('poly-rebuild-element-props-loft-rect-name');
            const loftRectWidthInput = document.getElementById('poly-rebuild-element-props-loft-rect-width-input');
            const loftRectHeightInput = document.getElementById('poly-rebuild-element-props-loft-rect-height-input');
            const loftRectFilletEnabledInput = document.getElementById('poly-rebuild-element-props-loft-rect-fillet-enabled');
            const loftRectFilletRadiusInput = document.getElementById('poly-rebuild-element-props-loft-rect-fillet-radius-input');
            const loftRectChamferEnabledInput = document.getElementById('poly-rebuild-element-props-loft-rect-chamfer-enabled');
            const loftRectChamferRadiusInput = document.getElementById('poly-rebuild-element-props-loft-rect-chamfer-radius-input');
            const loftRectAlignSelect = document.getElementById('poly-rebuild-element-props-loft-rect-align-select');
            const beamPage = document.getElementById('poly-rebuild-element-props-page-beam');
            const beamName = document.getElementById('poly-rebuild-element-props-beam-name');
            const slopePage = document.getElementById('poly-rebuild-element-props-page-slope');
            const openingPage = document.getElementById('poly-rebuild-element-props-page-opening');
            const doorPage = document.getElementById('poly-rebuild-element-props-page-door');
            const curtainPage = document.getElementById('poly-rebuild-element-props-page-curtain');
            const _hideAllElementPropsPages = () => {
                if (wallPage) wallPage.style.display = 'none';
                if (planePage) planePage.style.display = 'none';
                if (extrudePage) extrudePage.style.display = 'none';
                if (loftPage) loftPage.style.display = 'none';
                if (loftRectPage) loftRectPage.style.display = 'none';
                if (beamPage) beamPage.style.display = 'none';
                if (slopePage) slopePage.style.display = 'none';
                if (openingPage) openingPage.style.display = 'none';
                if (doorPage) doorPage.style.display = 'none';
                if (curtainPage) curtainPage.style.display = 'none';
            };
            if (!panel) return;
            if (!polyRebuildState.selectMode) {
                panel.style.display = 'none';
                polyRebuildState.elementPropsPanelOpen = false;
                _hideAllElementPropsPages();
                return;
            }

            const selectedIds = Array.from(polyRebuildState.selectedElementIds || []);
            let currentId = polyRebuildState.selectedElementLast;
            if ((!currentId || !polyRebuildState.selectedElementIds.has(currentId)) && selectedIds.length > 0) {
                currentId = selectedIds[0];
            }
            let currentObj = getPolyRebuildElementById(currentId);
            const openingEl = !currentObj && currentId ? polyRebuildState.openings.find(o => o && o.id === currentId) : null;
            if (!currentObj && !openingEl) {
                panel.style.display = 'none';
                polyRebuildState.elementPropsPanelOpen = false;
                _hideAllElementPropsPages();
                return;
            }
            if (openingEl && !currentObj) {
                panel.style.display = 'block';
                polyRebuildState.elementPropsPanelOpen = true;
                polyRebuildState.selectedElementLast = openingEl.id;
                _hideAllElementPropsPages();
                const isDoorEl = !!openingEl.hasDoorFrame;
                const isCurtainEl = !!openingEl.isCurtainWall;
                if (isDoorEl && doorPage) {
                    doorPage.style.display = 'block';
                    const doorNameSpan = document.getElementById('poly-rebuild-element-props-door-name');
                    if (doorNameSpan) doorNameSpan.textContent = openingEl.id;
                    const owInput = document.getElementById('poly-rebuild-element-props-door-width-input');
                    const ohInput = document.getElementById('poly-rebuild-element-props-door-height-input');
                    const oaInput = document.getElementById('poly-rebuild-element-props-door-altitude-input');
                    const ocInput = document.getElementById('poly-rebuild-element-props-door-centerline-offset-input');
                    const ooInput = document.getElementById('poly-rebuild-element-props-door-offset-input');
                    if (owInput) owInput.value = String((openingEl.width || POLY_DOOR_DEFAULT_WIDTH).toFixed(2));
                    if (ohInput) ohInput.value = String((openingEl.height || POLY_DOOR_DEFAULT_HEIGHT).toFixed(2));
                    if (oaInput) oaInput.value = String((openingEl.altitude || 0).toFixed(2));
                    if (ocInput) ocInput.value = String((openingEl.centerLineOffset || 0).toFixed(2));
                    if (ooInput) ooInput.value = String((openingEl.offsetAlongWall || 0).toFixed(2));
                    syncDoorSwingUiForOpening(openingEl, POLY_DOOR_UI_ELEMENT);
                } else if (isCurtainEl && curtainPage) {
                    curtainPage.style.display = 'block';
                    syncPolyRebuildElementCurtainPropsInputs(openingEl);
                } else if (!isDoorEl && !openingEl.hasWindowFrame && openingPage) {
                    openingPage.style.display = 'block';
                    const openingNameSpan = document.getElementById('poly-rebuild-element-props-opening-name');
                    if (openingNameSpan) openingNameSpan.textContent = openingEl.id;
                    const owInput = document.getElementById('poly-rebuild-element-props-opening-width-input');
                    const ohInput = document.getElementById('poly-rebuild-element-props-opening-height-input');
                    const oaInput = document.getElementById('poly-rebuild-element-props-opening-altitude-input');
                    const ocInput = document.getElementById('poly-rebuild-element-props-opening-centerline-offset-input');
                    const ooInput = document.getElementById('poly-rebuild-element-props-opening-offset-input');
                    if (owInput) owInput.value = String((openingEl.width || 1).toFixed(2));
                    if (ohInput) ohInput.value = String((openingEl.height || 2.1).toFixed(2));
                    if (oaInput) oaInput.value = String((openingEl.altitude || 0).toFixed(2));
                    if (ocInput) ocInput.value = String((openingEl.centerLineOffset || 0).toFixed(2));
                    if (ooInput) ooInput.value = String((openingEl.offsetAlongWall || 0).toFixed(2));
                }
                return;
            }

            if (currentId && polyRebuildState.selectedElementIds.has(currentId)) {
                polyRebuildState.selectedElementLast = currentId;
            } else {
                const resolvedId = getPolyRebuildElementId(currentObj);
                if (resolvedId) polyRebuildState.selectedElementLast = resolvedId;
            }
            panel.style.display = 'block';
            polyRebuildState.elementPropsPanelOpen = true;

            const displayName = currentObj.userData?.name || currentObj.name || '未命名元素';
            if (currentObj.userData?.isPolyRebuildWallRoot) {
                _hideAllElementPropsPages();
                if (wallPage) wallPage.style.display = 'block';
                if (wallName) wallName.textContent = displayName;
                const wallHeightValue = Number.isFinite(currentObj.userData?.wallHeight) ? currentObj.userData.wallHeight : Math.max(POLY_WALL_HEIGHT_MIN, polyRebuildState.wallHeight || 2.8);
                const wallThicknessValue = Number.isFinite(currentObj.userData?.wallThickness) ? currentObj.userData.wallThickness : Math.max(POLY_WALL_THICKNESS_MIN, polyRebuildState.wallThickness || 0.12);
                const wallBuildSettings = getPolyWallRootBuildSettings(currentObj);
                const wallCenterLineOffsetValue = wallBuildSettings.wallCenterLineOffset;
                const wallOffsetValue = wallBuildSettings.wallOffset;
                const alignMode = normalizePolyWallAlignMode(currentObj.userData?.polyWallAlignMode);
                const wallHeightLocked = isWallHeightLocked(currentObj);
                const wallThicknessLocked = isWallThicknessLocked(currentObj);
                if (wallHeightInput) wallHeightInput.value = String(wallHeightValue.toFixed(2));
                if (wallHeightInput) wallHeightInput.disabled = wallHeightLocked;
                if (wallHeightLockBtn) {
                    wallHeightLockBtn.innerText = wallHeightLocked ? '🔒' : '🔓';
                    wallHeightLockBtn.title = wallHeightLocked ? '墙高已锁定：禁止拖拽和输入修改墙高' : '墙高已解锁：允许拖拽和输入修改墙高';
                    wallHeightLockBtn.setAttribute('aria-pressed', wallHeightLocked ? 'true' : 'false');
                }
                if (wallThicknessInput) wallThicknessInput.value = String(wallThicknessValue.toFixed(2));
                if (wallThicknessInput) wallThicknessInput.disabled = wallThicknessLocked;
                if (wallThicknessLockBtn) {
                    wallThicknessLockBtn.innerText = wallThicknessLocked ? '🔒' : '🔓';
                    wallThicknessLockBtn.title = wallThicknessLocked ? '墙厚已锁定：禁止拖拽和输入修改墙厚' : '墙厚已解锁：允许拖拽和输入修改墙厚';
                    wallThicknessLockBtn.setAttribute('aria-pressed', wallThicknessLocked ? 'true' : 'false');
                }
                if (wallCenterLineOffsetInput) wallCenterLineOffsetInput.value = String(wallCenterLineOffsetValue.toFixed(2));
                if (wallOffsetInput) wallOffsetInput.value = String(wallOffsetValue.toFixed(2));
                if (wallAlignCenterBtn) wallAlignCenterBtn.classList.toggle('active-tool', alignMode === POLY_WALL_ALIGN_CENTER);
                if (wallAlignInnerBtn) wallAlignInnerBtn.classList.toggle('active-tool', alignMode === POLY_WALL_ALIGN_INNER);
                if (wallAlignOuterBtn) wallAlignOuterBtn.classList.toggle('active-tool', alignMode === POLY_WALL_ALIGN_OUTER);
            } else if (currentObj.userData?.isPolyRebuildAssistPlane) {
                _hideAllElementPropsPages();
                if (planePage) planePage.style.display = 'block';
                const isCeilingAssistPlane = getPolyRebuildAssistPlaneRole(currentObj) === 'ceiling';
                if (planeTitle) planeTitle.textContent = isCeilingAssistPlane ? '多边形元素（天花辅助平面）' : '多边形元素（辅助平面）';
                if (planeAlignClipBtn) planeAlignClipBtn.style.display = isCeilingAssistPlane ? 'none' : 'block';
                if (planeCopyBtn) planeCopyBtn.style.display = 'block';
                if (planeFullCopyBtn) planeFullCopyBtn.style.display = isCeilingAssistPlane ? 'none' : 'block';
                if (planeName) planeName.textContent = displayName;
                const planeSizeXValue = THREE.MathUtils.clamp(Number(currentObj.userData?.assistPlaneSizeX) || Number(currentObj.userData?.assistPlaneSize) || 2, 0.2, 60);
                const planeSizeYValue = THREE.MathUtils.clamp(Number(currentObj.userData?.assistPlaneSizeY) || Number(currentObj.userData?.assistPlaneSize) || 2, 0.2, 60);
                const planeGridValue = Math.max(0.02, Number(currentObj.userData?.assistPlaneGridStep) || polyRebuildState.assistPlaneGridStep || 0.1);
                if (planeSizeXInput) planeSizeXInput.value = String(planeSizeXValue.toFixed(2));
                if (planeSizeYInput) planeSizeYInput.value = String(planeSizeYValue.toFixed(2));
                if (planeGridInput) planeGridInput.value = String(planeGridValue.toFixed(2));
                syncPolyRebuildAssistPlaneWorldInputs(currentObj);
                syncPolyRebuildAssistPlaneLocalInputs(currentObj);
                const planeAdjBtn = document.getElementById('poly-rebuild-element-props-plane-adjust-btn');
                const planeAdjToolbar = document.getElementById('poly-rebuild-element-props-plane-adjust-toolbar');
                const planeAdjTransBtn = document.getElementById('poly-rebuild-element-props-plane-adjust-translate-btn');
                const planeAdjRotBtn = document.getElementById('poly-rebuild-element-props-plane-adjust-rotate-btn');
                if (planeAdjBtn) planeAdjBtn.style.background = isAssistPlaneAdjustActive ? '#c0392b' : '#0e7490';
                if (planeAdjToolbar) planeAdjToolbar.style.display = isAssistPlaneAdjustActive ? 'grid' : 'none';
                if (planeAdjTransBtn) {
                    planeAdjTransBtn.classList.toggle('active-tool', assistPlaneAdjustMode === 'translate');
                    planeAdjTransBtn.style.background = assistPlaneAdjustMode === 'translate' ? '#16a085' : '#475569';
                }
                if (planeAdjRotBtn) {
                    planeAdjRotBtn.classList.toggle('active-tool', assistPlaneAdjustMode === 'rotate');
                    planeAdjRotBtn.style.background = assistPlaneAdjustMode === 'rotate' ? '#16a085' : '#475569';
                }
            } else if (currentObj.userData?.isPolyRebuildExtrudeRoot || currentObj.userData?.isPolyRebuildFloorRoot || currentObj.userData?.isPolyRebuildCeilingRoot) {
                _hideAllElementPropsPages();
                if (extrudePage) extrudePage.style.display = 'block';
                const isFloorRoot = !!currentObj.userData?.isPolyRebuildFloorRoot;
                const isHoleRoot = !!currentObj.userData?.isPolyRebuildHoleRoot;
                const isPrismRoot = !!currentObj.userData?.isPolyRebuildPrismRoot;
                const isCeilingRoot = !!currentObj.userData?.isPolyRebuildCeilingRoot;
                const extrudeHeightLocked = isExtrudeHeightLocked(currentObj);
                if (extrudeTitle) extrudeTitle.textContent = isFloorRoot ? '多边形元素（地面）' : '多边形元素（挤出模型）';
                if (extrudeTitle && isHoleRoot) extrudeTitle.textContent = '多边形元素（开孔）';
                if (extrudeTitle && isCeilingRoot) extrudeTitle.textContent = '多边形元素（天花板）';
                if (extrudeHeightLabel) extrudeHeightLabel.textContent = isFloorRoot ? '地面高度(m)' : '挤出高度(m)';
                if (extrudeHeightLabel && isHoleRoot) extrudeHeightLabel.textContent = '开孔高度(m)';
                if (extrudeHeightLabel && isCeilingRoot) extrudeHeightLabel.textContent = '天花板厚度(m)';
                if (extrudeName) extrudeName.textContent = displayName;
                const hValue = Number(currentObj.userData?.extrudeHeight) || -0.1;
                const hSign = hValue < 0 ? 'neg' : 'pos';
                currentObj.userData.extrudeHeightSign = hSign;
                if (extrudeHeightInput) {
                    if (isCeilingRoot) {
                        extrudeHeightInput.min = '-9999';
                        extrudeHeightInput.max = '-0.01';
                        extrudeHeightInput.value = String(THREE.MathUtils.clamp(hValue, -9999, -0.01).toFixed(2));
                    } else if (isFloorRoot) {
                        extrudeHeightInput.min = '-9999';
                        extrudeHeightInput.max = '9999';
                        extrudeHeightInput.value = String(THREE.MathUtils.clamp(hValue, -9999, 9999).toFixed(2));
                    } else if (isHoleRoot) {
                        extrudeHeightInput.min = '-9999';
                        extrudeHeightInput.max = '9999';
                        extrudeHeightInput.value = String(THREE.MathUtils.clamp(hValue, -9999, 9999).toFixed(2));
                    } else if (isPrismRoot) {
                        extrudeHeightInput.min = '0';
                        extrudeHeightInput.max = '9999';
                        extrudeHeightInput.value = String(THREE.MathUtils.clamp(Math.abs(hValue), 0, 9999).toFixed(2));
                    } else {
                        extrudeHeightInput.min = '-9999';
                        extrudeHeightInput.max = '9999';
                        extrudeHeightInput.value = String(THREE.MathUtils.clamp(hValue, -9999, 9999).toFixed(2));
                    }
                    extrudeHeightInput.disabled = isPrismRoot ? extrudeHeightLocked : false;
                }
                if (extrudeHeightLockBtn) {
                    extrudeHeightLockBtn.style.display = isPrismRoot ? 'flex' : 'none';
                    extrudeHeightLockBtn.innerText = extrudeHeightLocked ? '🔒' : '🔓';
                    extrudeHeightLockBtn.title = extrudeHeightLocked
                        ? '方柱高度已锁定：禁止拖拽和输入修改挤出高度'
                        : '方柱高度已解锁：允许拖拽和输入修改挤出高度';
                    extrudeHeightLockBtn.setAttribute('aria-pressed', extrudeHeightLocked ? 'true' : 'false');
                }
                if (extrudeOffsetRow) extrudeOffsetRow.style.display = isFloorRoot ? 'none' : 'flex';
                if (!isFloorRoot && extrudeOffsetInput) {
                    const oValue = Number(currentObj.userData?.extrudeLineOffset) || 0;
                    const oSign = isHoleRoot
                        ? (oValue < 0 ? 'neg' : 'pos')
                        : (currentObj.userData?.extrudeOffsetSign === 'neg' || oValue < 0 ? 'neg' : 'pos');
                    currentObj.userData.extrudeOffsetSign = oSign;
                    if (isHoleRoot) {
                        extrudeOffsetInput.min = '-9999';
                        extrudeOffsetInput.max = '9999';
                        extrudeOffsetInput.value = String(THREE.MathUtils.clamp(oValue, -9999, 9999).toFixed(2));
                    } else {
                        extrudeOffsetInput.min = oSign === 'neg' ? '-9999' : '0';
                        extrudeOffsetInput.max = oSign === 'neg' ? '0' : '9999';
                        extrudeOffsetInput.value = String(oSign === 'neg'
                            ? THREE.MathUtils.clamp(oValue, -9999, 0).toFixed(2)
                            : THREE.MathUtils.clamp(oValue, 0, 9999).toFixed(2));
                    }
                }
            } else if (currentObj.userData?.isPolyRebuildLoftCircleRoot) {
                _hideAllElementPropsPages();
                if (loftPage) loftPage.style.display = 'block';
                if (loftName) loftName.textContent = displayName;
                const loftDiameter = Math.max(0.005, Number(currentObj.userData?.loftDiameter) || 0.05);
                const loftDiameterLocked = isLoftDiameterLocked(currentObj);
                const loftFilletEnabled = isLoftCornerFilletEnabled(currentObj);
                const loftFilletRadius = getLoftCornerFilletRadius(currentObj);
                const alignMode = normalizePolyLoftAlignMode(currentObj.userData?.loftAlignMode);
                if (loftDiameterInput) loftDiameterInput.value = String(loftDiameter.toFixed(3));
                if (loftDiameterInput) loftDiameterInput.disabled = loftDiameterLocked;
                if (loftFilletEnabledInput) loftFilletEnabledInput.checked = loftFilletEnabled;
                if (loftFilletRadiusInput) loftFilletRadiusInput.value = String(loftFilletRadius.toFixed(3));
                if (loftFilletRadiusInput) loftFilletRadiusInput.disabled = !loftFilletEnabled;
                const loftTubeSegs = Math.max(3, Number(currentObj.userData?.loftTubeSegments) || Number(polyRebuildState.loftCircleTubeSegments) || 12);
                if (loftTubeSegmentsInput) loftTubeSegmentsInput.value = String(loftTubeSegs);
                if (loftDiameterLockBtn) {
                    loftDiameterLockBtn.innerText = loftDiameterLocked ? '🔒' : '🔓';
                    loftDiameterLockBtn.title = loftDiameterLocked ? '圆截面直径已锁定：禁止拖拽和输入修改直径' : '圆截面直径已解锁：允许拖拽和输入修改直径';
                    loftDiameterLockBtn.setAttribute('aria-pressed', loftDiameterLocked ? 'true' : 'false');
                }
                if (loftAlignCenterBtn) loftAlignCenterBtn.classList.toggle('active-tool', alignMode === POLY_LOFT_ALIGN_CENTER);
                if (loftAlignTopBtn) loftAlignTopBtn.classList.toggle('active-tool', alignMode === POLY_LOFT_ALIGN_TOP);
                if (loftAlignBottomBtn) loftAlignBottomBtn.classList.toggle('active-tool', alignMode === POLY_LOFT_ALIGN_BOTTOM);
                if (loftAlignLeftBtn) loftAlignLeftBtn.classList.toggle('active-tool', alignMode === POLY_LOFT_ALIGN_LEFT);
                if (loftAlignRightBtn) loftAlignRightBtn.classList.toggle('active-tool', alignMode === POLY_LOFT_ALIGN_RIGHT);
            } else if (currentObj.userData?.isPolyRebuildLoftRectRoot) {
                _hideAllElementPropsPages();
                if (loftRectPage) loftRectPage.style.display = 'block';
                if (loftRectName) loftRectName.textContent = displayName;
                const rectWidth = Math.max(0.005, Number(currentObj.userData?.loftRectWidth) || 0.1);
                const rectHeight = Math.max(0.005, Number(currentObj.userData?.loftRectHeight) || 0.1);
                const rectFilletEnabled = isLoftRectCornerFilletEnabled(currentObj);
                const rectFilletRadius = getLoftRectCornerFilletRadius(currentObj);
                ensureLoftRectAlignAxes(currentObj);
                const rectAlignPreset = currentObj.userData.loftAlignPreset || 'center';
                if (loftRectWidthInput) loftRectWidthInput.value = String(rectWidth.toFixed(3));
                if (loftRectHeightInput) loftRectHeightInput.value = String(rectHeight.toFixed(3));
                const rectChamferEnabled = currentObj.userData?.loftRectChamferEnabled === true;
                const rectChamferRadius = Math.max(0.001, Number(currentObj.userData?.loftRectChamferRadius) || 0.005);
                if (loftRectFilletEnabledInput) loftRectFilletEnabledInput.checked = rectFilletEnabled;
                if (loftRectFilletRadiusInput) loftRectFilletRadiusInput.value = String(rectFilletRadius.toFixed(3));
                if (loftRectFilletRadiusInput) loftRectFilletRadiusInput.disabled = !rectFilletEnabled;
                if (loftRectChamferEnabledInput) loftRectChamferEnabledInput.checked = rectChamferEnabled;
                if (loftRectChamferRadiusInput) loftRectChamferRadiusInput.value = String(rectChamferRadius.toFixed(4));
                if (loftRectChamferRadiusInput) loftRectChamferRadiusInput.disabled = !rectChamferEnabled;
                if (loftRectAlignSelect) loftRectAlignSelect.value = rectAlignPreset;
            } else if (currentObj.userData?.isPolyRebuildBeamRoot) {
                _hideAllElementPropsPages();
                if (beamPage) beamPage.style.display = 'block';
                const segCount = getBeamSegments(currentObj).length;
                if (beamName) {
                    beamName.textContent = segCount > 1
                        ? `${displayName}（${segCount} 段）`
                        : displayName;
                }
            } else if (currentObj.userData?.isPolyRebuildSlopeVolumeRoot) {
                _hideAllElementPropsPages();
                if (slopePage) slopePage.style.display = 'block';
                syncSlopeVolumeElementPropsUi(currentObj);
            } else if (currentObj.userData?.isPolyRebuildSlopeNetworkRoot) {
                _hideAllElementPropsPages();
                const hostVol = currentObj.userData.hostSlopeVolumeRoot || currentObj.parent;
                if (slopePage) slopePage.style.display = 'block';
                if (hostVol?.userData?.isPolyRebuildSlopeVolumeRoot) {
                    syncSlopeVolumeElementPropsUi(hostVol);
                }
            } else if (currentObj.userData?.isPolyRebuildSuperEntityRoot) {
                _hideAllElementPropsPages();
                panel.style.display = 'none';
                polyRebuildState.elementPropsPanelOpen = false;
                const entity = findSuperEntityByRoot(currentObj);
                if (entity) {
                    const prevId = polyRebuildState.superEntitySelectedId;
                    polyRebuildState.superEntitySelectedId = entity.id;
                    syncSuperEntityUiFromDraft(entity);
                    if (typeof window.setRebuildPropsPanelOpen === 'function') {
                        window.setRebuildPropsPanelOpen(true, 'super-entity');
                    } else if (typeof setRebuildPropsPanelOpen === 'function') {
                        setRebuildPropsPanelOpen(true, 'super-entity');
                    }
                    if (prevId !== entity.id) {
                        scheduleUnionSuperEntityPriorityRefresh();
                    }
                }
            } else {
                const openingPage = document.getElementById('poly-rebuild-element-props-page-opening');
                const doorPageEl = document.getElementById('poly-rebuild-element-props-page-door');
                const openingEl = polyRebuildState.openings.find(o => o && o.id === currentId);
                if (openingEl) {
                    if (wallPage) wallPage.style.display = 'none';
                    if (planePage) planePage.style.display = 'none';
                    if (extrudePage) extrudePage.style.display = 'none';
                    if (openingPage) openingPage.style.display = 'none';
                    if (doorPageEl) doorPageEl.style.display = 'none';
                    const curtainPageEl = document.getElementById('poly-rebuild-element-props-page-curtain');
                    if (curtainPageEl) curtainPageEl.style.display = 'none';
                    if (openingEl.hasDoorFrame && doorPageEl) {
                        doorPageEl.style.display = 'block';
                        const doorNameEl = document.getElementById('poly-rebuild-element-props-door-name');
                        if (doorNameEl) doorNameEl.textContent = openingEl.id;
                        const owInput = document.getElementById('poly-rebuild-element-props-door-width-input');
                        const ohInput = document.getElementById('poly-rebuild-element-props-door-height-input');
                        const oaInput = document.getElementById('poly-rebuild-element-props-door-altitude-input');
                        const ocInput = document.getElementById('poly-rebuild-element-props-door-centerline-offset-input');
                        const ooInput = document.getElementById('poly-rebuild-element-props-door-offset-input');
                        if (owInput) owInput.value = String((openingEl.width || POLY_DOOR_DEFAULT_WIDTH).toFixed(2));
                        if (ohInput) ohInput.value = String((openingEl.height || POLY_DOOR_DEFAULT_HEIGHT).toFixed(2));
                        if (oaInput) oaInput.value = String((openingEl.altitude || 0).toFixed(2));
                        if (ocInput) ocInput.value = String((openingEl.centerLineOffset || 0).toFixed(2));
                        if (ooInput) ooInput.value = String((openingEl.offsetAlongWall || 0).toFixed(2));
                        syncDoorSwingUiForOpening(openingEl, POLY_DOOR_UI_ELEMENT);
                    } else if (openingEl.isCurtainWall && curtainPageEl) {
                        curtainPageEl.style.display = 'block';
                        syncPolyRebuildElementCurtainPropsInputs(openingEl);
                    } else if (!openingEl.hasDoorFrame && !openingEl.hasWindowFrame && openingPage) {
                        openingPage.style.display = 'block';
                        const openingNameEl = document.getElementById('poly-rebuild-element-props-opening-name');
                        if (openingNameEl) openingNameEl.textContent = openingEl.id;
                        const owInput = document.getElementById('poly-rebuild-element-props-opening-width-input');
                        const ohInput = document.getElementById('poly-rebuild-element-props-opening-height-input');
                        const oaInput = document.getElementById('poly-rebuild-element-props-opening-altitude-input');
                        const ocInput = document.getElementById('poly-rebuild-element-props-opening-centerline-offset-input');
                        const ooInput = document.getElementById('poly-rebuild-element-props-opening-offset-input');
                        if (owInput) owInput.value = String((openingEl.width || 1).toFixed(2));
                        if (ohInput) ohInput.value = String((openingEl.height || 2.1).toFixed(2));
                        if (oaInput) oaInput.value = String((openingEl.altitude || 0).toFixed(2));
                        if (ocInput) ocInput.value = String((openingEl.centerLineOffset || 0).toFixed(2));
                        if (ooInput) ooInput.value = String((openingEl.offsetAlongWall || 0).toFixed(2));
                    }
                } else {
                    panel.style.display = 'none';
                    polyRebuildState.elementPropsPanelOpen = false;
                    if (wallPage) wallPage.style.display = 'none';
                    if (planePage) planePage.style.display = 'none';
                    if (extrudePage) extrudePage.style.display = 'none';
                    if (openingPage) openingPage.style.display = 'none';
                    if (doorPageEl) doorPageEl.style.display = 'none';
                    const curtainPageEl2 = document.getElementById('poly-rebuild-element-props-page-curtain');
                    if (curtainPageEl2) curtainPageEl2.style.display = 'none';
                }
            }
        }

        function getCurrentPolyRebuildSelectedWallRoot() {
            const selectedIds = Array.from(polyRebuildState.selectedElementIds || []);
            let currentId = polyRebuildState.selectedElementLast;
            if (!currentId || !polyRebuildState.selectedElementIds.has(currentId)) currentId = selectedIds[0];
            const obj = getPolyRebuildElementById(currentId);
            if (obj && obj.userData?.isPolyRebuildWallRoot) return obj;
            for (let i = 0; i < selectedIds.length; i++) {
                const picked = getPolyRebuildElementById(selectedIds[i]);
                if (picked && picked.userData?.isPolyRebuildWallRoot) return picked;
            }
            return null;
        }

