        function getNextCloudColorMode(mode) {
            const normalized = normalizeCloudColorMode(mode);
            const idx = CLOUD_COLOR_MODE_CYCLE.indexOf(normalized);
            const nextIdx = (idx + 1) % CLOUD_COLOR_MODE_CYCLE.length;
            return CLOUD_COLOR_MODE_CYCLE[nextIdx];
        }

