                        const hitDelta = pressHit.clone().sub(planePoint);
                        const handleR = handleDelta.addScaledVector(axes.y, -handleDelta.dot(axes.y)).length();
                        const hitR = hitDelta.addScaledVector(axes.y, -hitDelta.dot(axes.y)).length();
                        grabRadialOffset = handleR - hitR;
