                    thicknessBasePoint: null,
                    thicknessRefPoint: null,
                    thicknessBothEnds: false,
                    thicknessAxis: null,
                    heightSignLock: null,
                    openingHeightLineBase: null,
                    openingDragStartHeightValue: null,
                    openingStartHeight: null,
                    openingStartAltitude: null,
                    openingWidthDragLineOrigin: null,
