                const tangentAxis = handleEntry.meta.tangentAxis.clone().normalize();
                rotateCenter = center.clone();
                rotateTangentAxis = tangentAxis.clone();
                rotateLeftAxis = handleEntry.meta.leftAxis ? handleEntry.meta.leftAxis.clone() : null;
                if (rotateLeftAxis && rotateLeftAxis.lengthSq() > 1e-10) rotateLeftAxis.normalize();
