                const _seedSegsRaw = Array.isArray(handleEntry.loftRoot.userData?.loftSegments) ? handleEntry.loftRoot.userData.loftSegments : [];
                const _seedRef = parseLoftNodeSelectionRef(rotateEndpointNodeId);
