                        const baseHeight = Number.isFinite(drag.openingStartHeight) ? drag.openingStartHeight : opening.height;
                        const heightRef = Math.max(POLY_OPENING_HEIGHT_MIN, Number(baseHeight) || POLY_OPENING_HEIGHT_MIN);
                        const maxAlt = 9999;
                        const minAlt = POLY_OPENING_ALTITUDE_MIN;
                        const requestedAlt = baseAlt + deltaHeight;
                        const unclampedAlt = THREE.MathUtils.clamp(requestedAlt, minAlt, maxAlt);
                        const desiredTopWorld = wallMin + unclampedAlt + heightRef;
