            const bindNumberInputDoubleClickSelectAll = (input) => {
                if (!input) return;
                input.addEventListener('dblclick', (e) => {
                    e.stopPropagation();
                    input.focus();
                    if (typeof input.select === 'function') input.select();
                    if (typeof input.setSelectionRange === 'function') {
                        const selectableType = !input.type || ['text', 'search', 'tel', 'url', 'password'].includes(String(input.type).toLowerCase());
                        if (selectableType) {
                            const valueLength = String(input.value || '').length;
                            try {
                                input.setSelectionRange(0, valueLength);
                            } catch (_) {}
                        }
                    }
                });
            };

