                    if (Number.isFinite(w)) polyRebuildState.beamWidth = THREE.MathUtils.clamp(w, 0.005, 50);
                    if (Number.isFinite(h)) polyRebuildState.beamHeight = THREE.MathUtils.clamp(h, 0.005, 50);
                    if (Number.isFinite(ho)) polyRebuildState.beamHeightOffset = clampBeamHeightOffset(ho);
