                        if (!selectedPlane) { showPickFeedback('请先选中辅助平面'); return; }
                        disablePolyRebuildSelectModeSoft('已退出选择模式，进入辅助平面移动');
                        if (assistPlaneRemeasureTarget || assistPlaneVerticalCorrectTarget) {
                            assistPlaneRemeasureTarget = null;
                            assistPlaneVerticalCorrectTarget = null;
                            assistPlaneVerticalCorrectBase1 = null;
                            clearPolyRebuildDraft('已退出重测/垂直修正模式');
                            setPolyRebuildTool(null);
                        }
                        assistPlaneAdjustMode = 'translate';
                        clearSuperEntityTransformMode();
                        polyTransformControl.attach(selectedPlane);
