                [polyRebuildOpeningWidthInput, polyRebuildOpeningHeightInput, polyRebuildOpeningAltitudeInput, polyRebuildOpeningCenterlineOffsetInput,
                 polyRebuildDoorWidthInput, polyRebuildDoorHeightInput, polyRebuildDoorAltitudeInput, polyRebuildDoorCenterlineOffsetInput,
                 polyRebuildElementOpeningWidthInput, polyRebuildElementOpeningHeightInput, polyRebuildElementOpeningAltitudeInput,
                 polyRebuildElementOpeningCenterlineOffsetInput, polyRebuildElementOpeningOffsetInput,
                 polyRebuildElementDoorWidthInput, polyRebuildElementDoorHeightInput, polyRebuildElementDoorAltitudeInput,
                 polyRebuildElementDoorCenterlineOffsetInput, polyRebuildElementDoorOffsetInput]
